const BOARD_WIDTH: usize = 10;
const BOARD_HEIGHT: usize = 20;
const INITIAL_SPEED_MS: u64 = 1000;
const MIN_SPEED_MS: u64 = 50;
const SPEED_DECREMENT_PER_LEVEL: u64 = 50;
const LINES_PER_LEVEL: usize = 10;

// Unicode block characters for rendering
const BLOCK_CHAR: char = '█';
const GHOST_CHAR: char = '░';
const EMPTY_CHAR: char = '·';

// ============================================================================
// Tetromino Definitions
// ============================================================================

#[derive(Clone, Copy, PartialEq, Eq)]
enum TetrominoType {
    I,
    O,
    T,
    S,
    Z,
    J,
    L,
}

impl TetrominoType {
    fn color(&self) -> Color {
        match self {
            TetrominoType::I => Color::Cyan,
            TetrominoType::O => Color::Yellow,
            TetrominoType::T => Color::Magenta,
            TetrominoType::S => Color::Green,
            TetrominoType::Z => Color::Red,
            TetrominoType::J => Color::Blue,
            TetrominoType::L => Color::Rgb { r: 255, g: 128, b: 0 },
        }
    }

    fn spawn_offsets(&self) -> (i32, i32) {
        // Spawn row is 0, column varies by piece
        match self {
            TetrominoType::I => (3, -1),
            TetrominoType::O => (4, 0),
            TetrominoType::T => (3, 0),
            TetrominoType::S => (3, 0),
            TetrominoType::Z => (3, 0),
            TetrominoType::J => (3, 0),
            TetrominoType::L => (3, 0),
        }
    }
}

// Rotation states: 0 = spawn, 1 = right, 2 = reverse, 3 = left
#[derive(Clone, Copy, PartialEq, Eq)]
enum RotationState {
    Spawn = 0,
    Right = 1,
    Reverse = 2,
    Left = 3,
}

impl RotationState {
    fn next_cw(&self) -> Self {
        match self {
            RotationState::Spawn => RotationState::Right,
            RotationState::Right => RotationState::Reverse,
            RotationState::Reverse => RotationState::Left,
            RotationState::Left => RotationState::Spawn,
        }
    }

    fn next_ccw(&self) -> Self {
        match self {
            RotationState::Spawn => RotationState::Left,
            RotationState::Left => RotationState::Reverse,
            RotationState::Reverse => RotationState::Right,
            RotationState::Right => RotationState::Spawn,
        }
    }

    fn as_usize(&self) -> usize {
        *self as usize
    }
}

// ============================================================================
// Piece Definition
// ============================================================================

#[derive(Clone)]
struct Piece {
    tetromino_type: TetrominoType,
    rotation: RotationState,
    x: i32,
    y: i32,
}

impl Piece {
    fn new(tetromino_type: TetrominoType) -> Self {
        let (x_offset, y_offset) = tetromino_type.spawn_offsets();
        Self {
            tetromino_type,
            rotation: RotationState::Spawn,
            x: (BOARD_WIDTH / 2) as i32 + x_offset,
            y: y_offset,
        }
    }

    fn get_cells(&self) -> Vec<(i32, i32)> {
        // Returns absolute board coordinates for each block in the piece
        let relative_cells = self.get_relative_cells();
        relative_cells
            .iter()
            .map(|(rx, ry)| (self.x + rx, self.y + ry))
            .collect()
    }

    fn get_relative_cells(&self) -> Vec<(i32, i32)> {
        // Returns cells relative to piece position based on type and rotation
        match self.tetromino_type {
            TetrominoType::I => self.i_cells(),
            TetrominoType::O => self.o_cells(),
            TetrominoType::T => self.t_cells(),
            TetrominoType::S => self.s_cells(),
            TetrominoType::Z => self.z_cells(),
            TetrominoType::J => self.j_cells(),
            TetrominoType::L => self.l_cells(),
        }
    }

    fn i_cells(&self) -> Vec<(i32, i32)> {
        match self.rotation {
            RotationState::Spawn | RotationState::Reverse => {
                vec![(-2, 0), (-1, 0), (0, 0), (1, 0)]
            }
            RotationState::Right | RotationState::Left => {
                vec![(0, -2), (0, -1), (0, 0), (0, 1)]
            }
        }
    }

    fn o_cells(&self) -> Vec<(i32, i32)> {
        // O piece doesn't rotate
        vec![(0, 0), (1, 0), (0, 1), (1, 1)]
    }

    fn t_cells(&self) -> Vec<(i32, i32)> {
        match self.rotation {
            RotationState::Spawn => vec![(-1, 0), (0, 0), (1, 0), (0, 1)],
            RotationState::Right => vec![(0, -1), (0, 0), (0, 1), (1, 0)],
            RotationState::Reverse => vec![(-1, 0), (0, 0), (1, 0), (0, -1)],
            RotationState::Left => vec![(0, -1), (0, 0), (0, 1), (-1, 0)],
        }
    }

    fn s_cells(&self) -> Vec<(i32, i32)> {
        match self.rotation {
            RotationState::Spawn | RotationState::Reverse => {
                vec![(0, 0), (1, 0), (-1, 1), (0, 1)]
            }
            RotationState::Right | RotationState::Left => {
                vec![(0, -1), (0, 0), (1, 0), (1, 1)]
            }
        }
    }

    fn z_cells(&self) -> Vec<(i32, i32)> {
        match self.rotation {
            RotationState::Spawn | RotationState::Reverse => {
                vec![(-1, 0), (0, 0), (0, 1), (1, 1)]
            }
            RotationState::Right | RotationState::Left => {
                vec![(1, -1), (0, 0), (1, 0), (0, 1)]
            }
        }
    }

    fn j_cells(&self) -> Vec<(i32, i32)> {
        match self.rotation {
            RotationState::Spawn => vec![(-1, 0), (0, 0), (1, 0), (-1, 1)],
            RotationState::Right => vec![(0, -1), (0, 0), (0, 1), (1, 1)],
            RotationState::Reverse => vec![(-1, 0), (0, 0), (1, 0), (1, -1)],
            RotationState::Left => vec![(0, -1), (0, 0), (0, 1), (-1, -1)],
        }
    }

    fn l_cells(&self) -> Vec<(i32, i32)> {
        match self.rotation {
            RotationState::Spawn => vec![(-1, 0), (0, 0), (1, 0), (1, 1)],
            RotationState::Right => vec![(0, -1), (0, 0), (0, 1), (1, -1)],
            RotationState::Reverse => vec![(-1, 0), (0, 0), (1, 0), (-1, -1)],
            RotationState::Left => vec![(0, -1), (0, 0), (0, 1), (-1, 1)],
        }
    }
}

