// ============================================================================
// Game Board
// ============================================================================

#[derive(Clone)]
struct Cell {
    filled: bool,
    color: Color,
}

struct Board {
    cells: [[Cell; BOARD_WIDTH]; BOARD_HEIGHT],
}

impl Board {
    fn new() -> Self {
        let cells = [[Cell { filled: false, color: Color::Reset }; BOARD_WIDTH]; BOARD_HEIGHT];
        Self { cells }
    }

    fn is_valid_position(&self, x: i32, y: i32) -> bool {
        if x < 0 || x >= BOARD_WIDTH as i32 {
            return false;
        }
        if y < 0 {
            return false;
        }
        if y >= BOARD_HEIGHT as i32 {
            return false;
        }
        true
    }

    fn is_cell_empty(&self, x: i32, y: i32) -> bool {
        if !self.is_valid_position(x, y) {
            return false;
        }
        !self.cells[y as usize][x as usize].filled
    }

    fn can_place(&self, piece: &Piece) -> bool {
        for (x, y) in piece.get_cells() {
            if !self.is_valid_position(x, y) {
                return false;
            }
            if !self.is_cell_empty(x, y) {
                return false;
            }
        }
        true
    }

    fn lock_piece(&mut self, piece: &Piece) {
        let color = piece.tetromino_type.color();
        for (x, y) in piece.get_cells() {
            if y >= 0 && y < BOARD_HEIGHT as i32 && x >= 0 && x < BOARD_WIDTH as i32 {
                self.cells[y as usize][x as usize] = Cell {
                    filled: true,
                    color,
                };
            }
        }
    }

    fn clear_full_lines(&mut self) -> Vec<usize> {
        let mut cleared_lines = Vec::new();
        let mut new_board = self.cells.clone();

        let mut write_y = BOARD_HEIGHT - 1;
        for read_y in (0..BOARD_HEIGHT).rev() {
            if !self.is_line_full(read_y) {
                new_board[write_y] = self.cells[read_y];
                write_y -= 1;
            } else {
                cleared_lines.push(read_y);
            }
        }

        // Clear remaining top rows
        for y in 0..=write_y {
            for x in 0..BOARD_WIDTH {
                new_board[y][x] = Cell { filled: false, color: Color::Reset };
            }
        }

        self.cells = new_board;
        cleared_lines
    }

    fn is_line_full(&self, y: usize) -> bool {
        (0..BOARD_WIDTH).all(|x| self.cells[y][x].filled)
    }

    fn get_ghost_y(&self, piece: &Piece) -> i32 {
        let mut ghost_y = piece.y;
        while self.can_place(&Piece {
            tetromino_type: piece.tetromino_type,
            rotation: piece.rotation,
            x: piece.x,
            y: ghost_y + 1,
        }) {
            ghost_y += 1;
        }
        ghost_y
    }
}

// ============================================================================
// T-Spin Detection
// ============================================================================

fn check_t_spin(piece: &Piece, board: &Board) -> bool {
    if !matches!(piece.tetromino_type, TetrominoType::T) {
        return false;
    }

    // Get the four corner cells around the T piece center
    let center = (piece.x, piece.y);

    // Calculate corner positions based on rotation
    let corners = match piece.rotation {
        RotationState::Spawn => {
            // T facing up: corners are at (-1,-1), (1,-1), (-1,1), (1,1) relative to center
            vec![(-1, -1), (1, -1), (-1, 1), (1, 1)]
        }
        RotationState::Right => {
            // T facing right
            vec![(-1, -1), (-1, 1), (1, -1), (1, 1)]
        }
        RotationState::Reverse => {
            // T facing down
            vec![(-1, -1), (1, -1), (-1, 1), (1, 1)]
        }
        RotationState::Left => {
            // T facing left
            vec![(-1, -1), (-1, 1), (1, -1), (1, 1)]
        }
    };

    // Count how many corners are occupied or out of bounds
    let mut occupied_corners = 0;
    for (dx, dy) in corners {
        let cx = center.0 + dx;
        let cy = center.1 + dy;
        if cx < 0 || cx >= BOARD_WIDTH as i32 || cy < 0 || cy >= BOARD_HEIGHT as i32 {
            occupied_corners += 1;
        } else if board.cells[cy as usize][cx as usize].filled {
            occupied_corners += 1;
        }
    }

    // T-spin requires at least 3 corners occupied
    occupied_corners >= 3
}

fn check_t_spin_mini(piece: &Piece, board: &Board) -> bool {
    if !matches!(piece.tetromino_type, TetrominoType::T) {
        return false;
    }

    // Mini T-spin: exactly 2 corners occupied (not 3 or 4)
    let center = (piece.x, piece.y);
    let corners = vec![(-1, -1), (1, -1), (-1, 1), (1, 1)];

    let mut occupied_corners = 0;
    for (dx, dy) in corners {
        let cx = center.0 + dx;
        let cy = center.1 + dy;
        if cx < 0 || cx >= BOARD_WIDTH as i32 || cy < 0 || cy >= BOARD_HEIGHT as i32 {
            occupied_corners += 1;
        } else if board.cells[cy as usize][cx as usize].filled {
            occupied_corners += 1;
        }
    }

    occupied_corners == 2
}

// ============================================================================
// Scoring System
// ============================================================================

struct Scoring {
    score: u64,
    lines_cleared: usize,
    level: usize,
    combo: i32,
    back_to_back: bool,
    last_tetris_was_back_to_back: bool,
}

impl Scoring {
    fn new() -> Self {
        Self {
            score: 0,
            lines_cleared: 0,
            level: 1,
            combo: -1,
            back_to_back: false,
            last_tetris_was_back_to_back: false,
        }
    }

    fn calculate_speed(&self) -> u64 {
        let speed = INITIAL_SPEED_MS - ((self.level - 1) as u64 * SPEED_DECREMENT_PER_LEVEL);
        speed.max(MIN_SPEED_MS)
    }

    fn add_lines(&mut self, lines: usize, was_t_spin: bool, t_spin_type: Option<&str>) {
        let base_scores = [
            (1, 100),
            (2, 300),
            (3, 500),
            (4, 800), // Tetris
        ];

        if lines == 0 {
            self.combo = -1;
            return;
        }

        self.lines_cleared += lines;
        let old_level = self.level;
        self.level = (self.lines_cleared / LINES_PER_LEVEL) + 1;

        // Base score
        let base = if lines <= 4 { base_scores[lines - 1] } else { (lines, 0) }.1;

        // Apply level multiplier
        let mut points = base * self.level as u64;

        // T-Spin bonus
        if was_t_spin {
            let t_spin_scores = [
                (true, 400),   // T-Spin Single
                (true, 800),   // T-Spin Double
                (true, 1200),  // T-Spin Triple
                (false, 100),  // Mini T-Spin Single
                (false, 200),  // Mini T-Spin Double
                (false, 400),  // Mini T-Spin Triple (rare)
            ];

            let is_regular = t_spin_type == Some("regular");
            let t_spin_idx = match (lines, is_regular) {
                (1, true) => 0,
                (2, true) => 1,
                (3, true) => 2,
                (1, false) => 3,
                (2, false) => 4,
                _ => 5,
            };
            points = t_spin_scores[t_spin_idx].1 * self.level as u64;
        }

        // Back-to-Back bonus (for Tetrises and T-Spins)
        let is_btb_eligible = lines == 4 || was_t_spin;
        if is_btb_eligible {
            if self.back_to_back || self.last_tetris_was_back_to_back {
                points = points + points / 2; // 50% bonus
                self.back_to_back = true;
            } else if lines == 4 {
                self.back_to_back = true;
            }
            self.last_tetris_was_back_to_back = is_btb_eligible;
        } else {
            self.back_to_back = false;
        }

        // Combo bonus
        self.combo += 1;
        if self.combo > 0 {
            let combo_bonus = 50 * self.combo as u64 * self.level as u64;
            points += combo_bonus;
        }

        self.score += points;
    }
}

// ============================================================================
// Bag Randomizer (7-Bag)
// ============================================================================

struct BagRandomizer {
    bag: Vec<TetrominoType>,
    index: usize,
}

impl BagRandomizer {
    fn new() -> Self {
        let mut bag = vec![
            TetrominoType::I,
            TetrominoType::O,
            TetrominoType::T,
            TetrominoType::S,
            TetrominoType::Z,
            TetrominoType::J,
            TetrominoType::L,
        ];
        let mut rng = rand::thread_rng();
        bag.shuffle(&mut rng);
        Self { bag, index: 0 }
    }

    fn next(&mut self) -> TetrominoType {
        if self.index >= self.bag.len() {
            // Refill bag
            self.bag = vec![
                TetrominoType::I,
                TetrominoType::O,
                TetrominoType::T,
                TetrominoType::S,
                TetrominoType::Z,
                TetrominoType::J,
                TetrominoType::L,
            ];
            let mut rng = rand::thread_rng();
            self.bag.shuffle(&mut rng);
            self.index = 0;
        }
        let piece = self.bag[self.index];
        self.index += 1;
        piece
    }
}

// ============================================================================
// Next Pieces Queue
// ============================================================================

struct NextQueue {
    pieces: Vec<TetrominoType>,
    randomizer: BagRandomizer,
}

impl NextQueue {
    fn new() -> Self {
        let mut randomizer = BagRandomizer::new();
        let pieces = (0..5).map(|_| randomizer.next()).collect();
        Self { pieces, randomizer }
    }

    fn pop(&mut self) -> TetrominoType {
        let piece = self.pieces.remove(0);
        self.pieces.push(self.randomizer.next());
        piece
    }

    fn peek(&self, index: usize) -> TetrominoType {
        if index < self.pieces.len() {
            self.pieces[index]
        } else {
            TetrominoType::T // Default fallback
        }
    }
}

// ============================================================================
// Game State
// ============================================================================

struct Game {
    board: Board,
    current_piece: Option<Piece>,
    hold_piece: Option<TetrominoType>,
    can_hold: bool,
    next_queue: NextQueue,
    scoring: Scoring,
    game_over: bool,
    paused: bool,
    last_fall_time: Instant,
    lock_delay_start: Option<Instant>,
    lock_delay_duration: Duration,
    t_spin_pending: bool,
    t_spin_type: Option<String>,
}

impl Game {
    fn new() -> Self {
        Self {
            board: Board::new(),
            current_piece: None,
            hold_piece: None,
            can_hold: true,
            next_queue: NextQueue::new(),
            scoring: Scoring::new(),
            game_over: false,
            paused: false,
            last_fall_time: Instant::now(),
            lock_delay_start: None,
            lock_delay_duration: Duration::from_millis(500),
            t_spin_pending: false,
            t_spin_type: None,
        }
    }

    fn spawn_piece(&mut self) {
        let tetromino_type = self.next_queue.pop();
        let piece = Piece::new(tetromino_type);

        if !self.board.can_place(&piece) {
            self.game_over = true;
            return;
        }

        self.current_piece = Some(piece);
        self.can_hold = true;
        self.lock_delay_start = None;
        self.t_spin_pending = false;
        self.t_spin_type = None;
    }

    fn hold_current_piece(&mut self) {
        if !self.can_hold {
            return;
        }

        let current = self.current_piece.take().unwrap();
        let current_type = current.tetromino_type;

        if let Some(held) = self.hold_piece {
            self.hold_piece = Some(current_type);
            let new_piece = Piece::new(held);
            if self.board.can_place(&new_piece) {
                self.current_piece = Some(new_piece);
            } else {
                self.game_over = true;
            }
        } else {
            self.hold_piece = Some(current_type);
            self.spawn_piece();
        }

        self.can_hold = false;
    }

    fn move_piece(&mut self, dx: i32, dy: i32) -> bool {
        if let Some(piece) = &mut self.current_piece {
            let new_piece = Piece {
                tetromino_type: piece.tetromino_type,
                rotation: piece.rotation,
                x: piece.x + dx,
                y: piece.y + dy,
            };
            if self.board.can_place(&new_piece) {
                *piece = new_piece;
                if dy > 0 {
                    self.lock_delay_start = None;
                }
                return true;
            }
        }
        false
    }

    fn rotate_piece(&mut self, clockwise: bool) {
        if self.current_piece.is_none() {
            return;
        }

        let piece = self.current_piece.unwrap();
        let from_rot = piece.rotation;
        let to_rot = if clockwise {
            from_rot.next_cw()
        } else {
            from_rot.next_ccw()
        };

        let wall_kicks = get_wall_kicks(&piece, from_rot, to_rot);

        for (kick_x, kick_y) in wall_kicks.iter() {
            let rotated = Piece {
                tetromino_type: piece.tetromino_type,
                rotation: to_rot,
                x: piece.x + kick_x,
                y: piece.y - kick_y, // Note: y kick is inverted
            };
            if self.board.can_place(&rotated) {
                self.current_piece = Some(rotated);

                // Check for T-spin on rotation
                if !self.t_spin_pending && check_t_spin(&rotated, &self.board) {
                    self.t_spin_pending = true;
                    if check_t_spin_mini(&rotated, &self.board) && !check_t_spin(&rotated, &self.board) {
                        self.t_spin_type = Some("mini".to_string());
                    } else {
                        self.t_spin_type = Some("regular".to_string());
                    }
                }

                // Reset lock delay on successful rotation
                self.lock_delay_start = None;
                return;
            }
        }
    }

    fn soft_drop(&mut self) {
        if self.move_piece(0, 1) {
            self.scoring.score += 1; // Soft drop point
        }
    }

    fn hard_drop(&mut self) {
        if let Some(piece) = &self.current_piece {
            let ghost_y = self.board.get_ghost_y(piece);
            let drop_distance = ghost_y - piece.y;
            self.scoring.score += drop_distance as u64 * 2; // Hard drop points
            self.current_piece.as_mut().unwrap().y = ghost_y;
            self.lock_piece();
        }
    }

    fn lock_piece(&mut self) {
        if let Some(piece) = &self.current_piece {
            self.board.lock_piece(piece);

            let was_t_spin = self.t_spin_pending;
            let t_spin_type = self.t_spin_type.clone();

            let cleared_lines = self.board.clear_full_lines();
            self.scoring.add_lines(cleared_lines.len(), was_t_spin, t_spin_type.as_deref());

            self.spawn_piece();
        }
    }

    fn update(&mut self) {
        if self.game_over || self.paused || self.current_piece.is_none() {
            return;
        }

        let speed = Duration::from_millis(self.scoring.calculate_speed());
        let now = Instant::now();

        // Check if piece should fall
        if now.duration_since(self.last_fall_time) >= speed {
            if !self.move_piece(0, 1) {
                // Piece landed
                if self.lock_delay_start.is_none() {
                    self.lock_delay_start = Some(now);
                }
            } else {
                self.lock_delay_start = None;
            }
            self.last_fall_time = now;
        }

        // Check lock delay
        if let Some(lock_start) = self.lock_delay_start {
            if now.duration_since(lock_start) >= self.lock_delay_duration {
                self.lock_piece();
            }
        }
    }

    fn handle_input(&mut self, key: KeyCode) {
        if self.game_over {
            if matches!(key, KeyCode::Enter) {
                // Restart game
                *self = Game::new();
            }
            return;
        }

        if self.paused {
            if matches!(key, KeyCode::Char('p') | KeyCode::Char(' ')) {
                self.paused = false;
            }
            return;
        }

        match key {
            KeyCode::Left | KeyCode::Char('a') => {
                self.move_piece(-1, 0);
            }
            KeyCode::Right | KeyCode::Char('d') => {
                self.move_piece(1, 0);
            }
            KeyCode::Down | KeyCode::Char('s') => {
                self.soft_drop();
            }
            KeyCode::Up | KeyCode::Char('w') => {
                self.rotate_piece(true);
            }
            KeyCode::Char('z') | KeyCode::Char('q') => {
                self.rotate_piece(false);
            }
            KeyCode::Space => {
                self.hard_drop();
            }
            KeyCode::Char('c') | KeyCode::Char('h') | KeyCode::Shift => {
                self.hold_current_piece();
            }
            KeyCode::Char('p') | KeyCode::Char(' ') => {
                self.paused = true;
            }
            _ => {}
        }
    }
}

