fn render_game(game: &Game, offset_x: usize, offset_y: usize) -> Vec<String> {
    let mut output = Vec::new();

    // Draw hold piece
    let hold_label = "HOLD";
    output.push(format!("{}{}{}", 
        SetForegroundColor(Color::White),
        hold_label,
        ResetColor
    ));

    if let Some(held) = game.hold_piece {
        let preview = render_mini_piece(held, game.can_hold);
        for line in preview {
            output.push(line);
        }
    } else {
        for _ in 0..4 {
            output.push("    ".to_string());
        }
    }

    output.push("".to_string()); // Spacer

    // Draw next queue
    let next_label = "NEXT";
    output.push(format!("{}{}{}", 
        SetForegroundColor(Color::White),
        next_label,
        ResetColor
    ));

    for i in 0..5 {
        let piece_type = game.next_queue.peek(i);
        let preview = render_mini_piece(piece_type, true);
        for line in preview {
            output.push(line);
        }
        output.push("".to_string());
    }

    output.push("".to_string()); // Spacer

    // Draw stats
    output.push(format!("{}SCORE{}", SetForegroundColor(Color::Yellow), ResetColor));
    output.push(format!("  {}", game.scoring.score));

    output.push(format!("{}LEVEL{}", SetForegroundColor(Color::Cyan), ResetColor));
    output.push(format!("  {}", game.scoring.level));

    output.push(format!("{}LINES{}", SetForegroundColor(Color::Green), ResetColor));
    output.push(format!("  {}", game.scoring.lines_cleared));

    if game.scoring.combo > 0 {
        output.push(format!("{}COMBO{}", SetForegroundColor(Color::Magenta), ResetColor));
        output.push(format!("  {}x", game.scoring.combo));
    }

    if game.scoring.back_to_back {
        output.push(format!("{}B2B{}", SetForegroundColor(Color::Red), ResetColor));
        output.push("  ON".to_string());
    }

    output
}

fn render_mini_piece(tetromino_type: TetrominoType, active: bool) -> Vec<String> {
    let piece = Piece::new(tetromino_type);
    let color = if active { tetromino_type.color() } else { Color::DarkGrey };

    // Create a mini 4x4 preview
    let mut grid = [[false; 4]; 4];
    for (x, y) in piece.get_relative_cells() {
        // Center the piece in the 4x4 grid
        let gx = (x + 2).clamp(0, 3) as usize;
        let gy = (y + 1).clamp(0, 3) as usize;
        if gx < 4 && gy < 4 {
            grid[gy][gx] = true;
        }
    }

    let mut result = Vec::new();
    for row in grid.iter() {
        let line: String = row.iter().map(|&filled| {
            if filled {
                format!("{}{}{}", SetForegroundColor(color), BLOCK_CHAR, ResetColor)
            } else {
                " ".to_string()
            }
        }).collect();
        result.push(line);
    }
    result
}

fn render_board(game: &Game) -> Vec<String> {
    let mut output = Vec::new();

    // Top border
    let top_border: String = (0..BOARD_WIDTH).map(|_| "══").collect();
    output.push(format!("╔{}╗", top_border));

    // Board rows
    for y in 0..BOARD_HEIGHT {
        let mut row = String::from("║");

        for x in 0..BOARD_WIDTH {
            let cell = &game.board.cells[y][x];

            // Check if current piece occupies this cell
            let current_color = game.current_piece.as_ref().and_then(|p| {
                for (px, py) in p.get_cells() {
                    if px == x as i32 && py == y as i32 {
                        return Some(p.tetromino_type.color());
                    }
                }
                None
            });

            // Check if ghost piece occupies this cell
            let ghost_color = game.current_piece.as_ref().and_then(|p| {
                let ghost_y = game.board.get_ghost_y(p);
                for (px, py) in p.get_cells() {
                    let gy = ghost_y + (py - p.y);
                    if px == x as i32 && gy == y as i32 && !cell.filled && current_color.is_none() {
                        return Some(p.tetromino_type.color());
                    }
                }
                None
            });

            if let Some(color) = current_color {
                row.push_str(&format!("{}{}{}", SetForegroundColor(color), BLOCK_CHAR, ResetColor));
            } else if cell.filled {
                row.push_str(&format!("{}{}{}", SetForegroundColor(cell.color), BLOCK_CHAR, ResetColor));
            } else if let Some(color) = ghost_color {
                row.push_str(&format!("{}{}{}", SetForegroundColor(color), GHOST_CHAR, ResetColor));
            } else {
                row.push(EMPTY_CHAR);
            }
        }

        row.push('║');
        output.push(row);
    }

    // Bottom border
    output.push(format!("╚{}╝", top_border));

    output
}

fn render_full_screen(game: &Game) -> Vec<String> {
    let mut output = Vec::new();

    // Clear screen and move to top
    output.push(format!("{}{}", Clear(ClearType::All), MoveTo(0, 0)));

    // Title
    output.push(format!("{}╔════════════════════════════════════════════════╗{}", 
        SetForegroundColor(Color::Rgb { r: 255, g: 215, b: 0 }), ResetColor));
    output.push(format!("{}║           {}T E T R I S{}                      ║{}", 
        SetForegroundColor(Color::Rgb { r: 255, g: 215, b: 0 }),
        SetForegroundColor(Color::Red), ResetColor,
        ResetColor));
    output.push(format!("{}╚════════════════════════════════════════════════╝{}", 
        SetForegroundColor(Color::Rgb { r: 255, g: 215, b: 0 }), ResetColor));
    output.push("".to_string());

    // Render side panel and board
    let side = render_game(game, 0, 0);
    let board = render_board(game);

    // Combine side and board
    let max_height = side.len().max(board.len());
    for i in 0..max_height {
        let side_line = side.get(i).unwrap_or(&String::new());
        let board_line = board.get(i).unwrap_or(&String::new());
        output.push(format!("{}  {}", side_line, board_line));
    }

    output.push("".to_string());

    // Controls
    output.push(format!("{}CONTROLS{}", SetForegroundColor(Color::White), ResetColor));
    output.push("  ←/A: Move left    →/D: Move right    ↓/S: Soft drop".to_string());
    output.push("  ↑/W: Rotate CW    Z/Q: Rotate CCW    Space: Hard drop".to_string());
    output.push("  C/H: Hold piece   P: Pause           Enter: Restart (game over)".to_string());

    if game.paused {
        output.push("".to_string());
        output.push(format!("{}  PAUSED - Press P or Space to resume{}", 
            SetForegroundColor(Color::Yellow), ResetColor));
    }

    if game.game_over {
        output.push("".to_string());
        output.push(format!("{}  GAME OVER - Press Enter to restart{}", 
            SetForegroundColor(Color::Red), ResetColor));
    }

    output
}

// ============================================================================
// Main Game Loop
// ============================================================================

fn run_game() -> Result<(), Box<dyn std::error::Error>> {
    let mut stdout = stdout();

    // Setup terminal
    terminal::enable_raw_mode()?;
    execute!(stdout, EnterAlternateScreen, Hide)?;

    let mut game = Game::new();
    game.spawn_piece();

    let mut last_render = Instant::now();
    let render_interval = Duration::from_millis(50);

    loop {
        // Handle input
        if poll(Duration::from_millis(16))? {
            if let Event::Key(key_event) = read()? {
                if key_event.kind == KeyEventKind::Press {
                    game.handle_input(key_event.code);
                }
            }
        }

        // Update game state
        game.update();

        // Render
        if last_render.elapsed() >= render_interval {
            let output = render_full_screen(&game);
            let mut y = 0;
            for line in output {
                execute!(stdout, MoveTo(0, y as u16), Print(&line))?;
                y += 1;
            }
            stdout.flush()?;
            last_render = Instant::now();
        }

        // Check for quit
        if game.game_over {
            // Wait for restart or quit
            if poll(Duration::from_millis(100))? {
                if let Event::Key(key_event) = read()? {
                    if key_event.kind == KeyEventKind::Press {
                        if matches!(key_event.code, KeyCode::Esc) {
                            break;
                        }
                        if matches!(key_event.code, KeyCode::Enter) {
                            game = Game::new();
                            game.spawn_piece();
                        }
                    }
                }
            }
        }
    }

    // Cleanup terminal
    terminal::disable_raw_mode()?;
    execute!(stdout, Show, LeaveAlternateScreen)?;

    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    run_game()
}
